								<td align="left" valign="middle"><a href="http://masslinemedia.com/smf/index.php?topic=11.msg45#msg45"><img src="http://masslinemedia.com/smf/Themes/safgrey105/images/post/xx.gif" alt="" border="0" /></a></td>
								<td align="left" valign="middle">
									<b><a href="http://masslinemedia.com/smf/index.php?topic=11.msg45#msg45">Mumia on the Philippines</a></b>
									<div class="smalltext">&#171; <b> on:</b> October 03, 2006, 10:41:01 pm &#187;</div></td>
								<td align="right" valign="bottom" height="20" nowrap="nowrap" style="font-size: smaller;">
